// Generated-table interface for the SPIR-V grammar.
//
// grammar_tables.cpp is GENERATED by scripts/gen_grammar_tables.py from the
// JSON grammars in the pinned SPIRV-Headers source and checked in. Everything here is
// structural knowledge derived from the SPIR-V specification — no
// corpus-trained data.
#pragma once

#include <cstdint>
#include <string_view>

namespace arixv {
inline namespace v1 {

// Collapses the grammar's operand kinds into the categories the codec
// distinguishes. Specific kinds still matter for context selection; the
// tracker also sees the raw kind index.
enum class OperandCategory : uint8_t {
  kIdResult,
  kIdResultType,
  kIdRef,
  kIdScope,            // IdScope: an ID that must name a scope constant
  kIdMemorySemantics,  // IdMemorySemantics: ID naming a semantics constant
  kValueEnum,
  kBitEnum,
  kLiteralInteger,
  kLiteralString,
  kLiteralContextDependentNumber,
  kLiteralExtInstInteger,
  kLiteralSpecConstantOpInteger,
  kComposite,  // Pair* kinds; components listed per kind
  kUnknown,
};

enum class Quantifier : uint8_t {
  kOne,       // exactly one occurrence
  kOptional,  // ? — zero or one
  kVariadic,  // * — zero or more
};

enum class InstructionTypeClass : uint8_t {
  kOther = 0,
  kVoid,
  kBool,
  kInt,
  kFloat,
  kVector,
  kMatrix,
  kPointer,
  kStruct,
  kArray,
  kRuntimeArray,
  kImage,
  kSampler,
  kSampledImage,
  kFunction,
};

enum InstructionFlags : uint16_t {
  kInstTerminator = 1u << 0,
  kInstDeclaresType = 1u << 1,
  kInstVariable = 1u << 2,
  kInstFunction = 1u << 3,
  kInstFunctionEnd = 1u << 4,
  kInstLabel = 1u << 5,
  kInstExtInstImport = 1u << 6,
  kInstString = 1u << 7,
  kInstExtInst = 1u << 8,
  kInstTypeWidth = 1u << 9,
  kInstTypeComponent = 1u << 10,
  kInstTypePointer = 1u << 11,
  kInstTypeFunction = 1u << 12,
  kInstConstantNumber = 1u << 13,
  // !fixed_word_count, all slots required (kOne) and self-delimiting
  // (LiteralString, ValueEnum/BitEnum, or kInstConstantNumber's
  // LiteralContextDependentNumber).
  kInstGrammarImpliedWordCount = 1u << 14,
  // !fixed_word_count, fixed-one-word required prefix followed by one or more
  // self-delimiting optional (?) tail slots (no *).
  kInstOptionalTail = 1u << 15,
};

// One enumerant of a ValueEnum/BitEnum kind. Parameters are operand kinds
// that follow the enum word when this enumerant is present (e.g.
// MemoryAccess.Aligned carries a LiteralInteger).
struct EnumerantDesc {
  uint32_t value;
  uint16_t first_param;  // index into kEnumParamKinds
  uint8_t num_params;
};

struct OperandKindDesc {
  // Enums: enumerants sorted ascending by value (aliases deduped, first name
  // in grammar order kept). Empty otherwise.
  uint16_t first_enumerant;
  uint16_t num_enumerants;
  // Composites: component kind indices into kOperandKinds. Empty otherwise.
  uint16_t first_component;
  OperandCategory category;
  uint8_t num_components;
};
static_assert(sizeof(OperandKindDesc) == 8, "OperandKindDesc layout changed");

// One slot of an instruction's operand layout (result and result-type appear
// as slots too, in grammar order).
struct OperandSlotDesc {
  uint8_t kind;  // index into kOperandKinds
  Quantifier quantifier;
};
static_assert(sizeof(OperandSlotDesc) == 2, "OperandSlotDesc layout changed");

struct InstructionDesc {
  uint16_t opcode;  // core opcode, or extended-instruction number
  uint16_t first_operand;  // index into the owning table's operand slot array
  // Minimum legal word count: 1 (opcode word) + one word per required slot.
  uint16_t min_word_count;
  uint16_t flags;   // InstructionFlags
  uint8_t num_operands;
  uint8_t instruction_class;  // InstructionClass (core) / 0 (ext inst sets)
  uint8_t result_bucket;      // result-ID delta context bucket
  InstructionTypeClass type_class;
  uint8_t section;  // Section value; kept as uint8_t to avoid tracker coupling.
  // Fixed word index of the operand the tracker reads at instruction end:
  // the type width (kInstTypeWidth), component/pointee/return type
  // (kInstTypeComponent/kInstTypePointer/kInstTypeFunction), or first word
  // of the import name string (kInstExtInstImport). 0 when none. The
  // generator guarantees the operand is required, every slot before it is a
  // required one-word operand, and — for all instructions with results —
  // that the result type sits at word 1 with the result ID directly after
  // it, so aux_word < min_word_count and result positions are fixed.
  uint8_t aux_word;
  // Packed boolean flags so InstructionDesc fits in 16 bytes with zero
  // pointer relocations.
  uint8_t has_result : 1;
  uint8_t has_result_type : 1;
  // True iff every slot is quantifier kOne with a guaranteed one-word kind
  // (Ids, LiteralInteger/ExtInstInteger, enums whose enumerants all have zero
  // params) — i.e. word count is exactly min_word_count for valid input.
  uint8_t fixed_word_count : 1;
};
static_assert(sizeof(InstructionDesc) == 16, "InstructionDesc layout changed");

inline bool HasInstructionFlag(const InstructionDesc* desc,
                               InstructionFlags flag) {
  return desc && (desc->flags & static_cast<uint16_t>(flag)) != 0;
}

// InstructionClass values are generated from the distinct "class" strings in
// the core grammar (e.g. Type-Declaring, Constant-Creation, Annotation,
// Control-Flow ...); exposed here as an opaque small integer so the model can
// use it as a context input without hardcoding. Diagnostic names live in
// grammar_names.h.
uint8_t NumInstructionClasses();

// --- Core grammar lookups ------------------------------------------------

// Binary search by opcode; nullptr if unknown. Duplicate opcodes (aliases
// like OpDecorateStringGOOGLE) are deduped to one entry.
const InstructionDesc* FindInstruction(uint32_t opcode);

// Dense-index access to the core instruction table (sorted by opcode); the
// opcode model codes indices, not raw opcodes.
uint16_t NumCoreInstructions();
const InstructionDesc& GetCoreInstruction(uint16_t index);
int FindInstructionIndex(uint32_t opcode);  // -1 if unknown

const OperandKindDesc& GetOperandKind(uint16_t kind_index);
uint16_t NumOperandKinds();
uint16_t GetValueEnumOrdinal(uint16_t kind_index);
uint16_t NumValueEnumKinds();

// Slots for a core instruction (indexes resolved against the core tables).
const OperandSlotDesc* GetOperandSlots(const InstructionDesc& inst);

// Enum params / composite components referenced by the descs above.
const uint16_t* GetEnumParamKinds(const EnumerantDesc& e);
const uint16_t* GetCompositeComponents(const OperandKindDesc& kind);

// Enumerant with exactly this value (works for ValueEnum, and for BitEnum
// single-bit values); nullptr if absent.
const EnumerantDesc* FindEnumerant(const OperandKindDesc& kind, uint32_t value);
const EnumerantDesc& GetEnumerant(const OperandKindDesc& kind,
                                  uint16_t index);

// --- Extended instruction sets -------------------------------------------

struct ExtInstSetDesc {
  uint16_t name_offset;         // byte offset into kStringPrimer (NUL-terminated)
  uint16_t first_instruction;   // index into kExtInstructions
  uint16_t num_instructions;
  uint16_t first_operand_slot;  // index into kExtOperandSlots
};
static_assert(sizeof(ExtInstSetDesc) == 8, "ExtInstSetDesc layout changed");

// Canonical OpExtInstImport literal, e.g. "GLSL.std.450".
const char* GetExtInstSetName(const ExtInstSetDesc& set);

// Exact match on the canonical name, then prefix match for versioned set
// names (e.g. "NonSemantic.ClspvReflection.5"); nullptr if unknown.
const ExtInstSetDesc* FindExtInstSet(std::string_view import_name);
uint16_t NumExtInstSets();
int FindExtInstSetIndex(const ExtInstSetDesc* set);  // -1 if not generated

const InstructionDesc* GetExtInstructions(const ExtInstSetDesc& set);
const InstructionDesc* FindExtInstruction(const ExtInstSetDesc& set,
                                          uint32_t ext_opcode);
const OperandSlotDesc* GetExtOperandSlots(const ExtInstSetDesc& set,
                                          const InstructionDesc& inst);

// --- Grammar strings ----------------------------------------------------

// Sorted extension and extended-instruction-set names from the grammar.
uint16_t NumGrammarStrings();
const char* GetGrammarString(uint16_t index);
// Every core enumerant name, then the grammar strings, each NUL-terminated:
// the string model's initial match history.
std::string_view GetStringPrimer();
// The string match table after inserting the primer (generated constant
// data, see StringMatchTable in model.cpp); *bits receives its log2 size.
const uint32_t* GetPrimedStringMatchTable(int* bits);

// --- Well-known values the tracker needs by name --------------------------

// Kind indices for the handful of kinds the tracker special-cases; generated
// as constants so they never drift from the tables.
struct WellKnownKinds {
  uint16_t id_result;
  uint16_t id_result_type;
  uint16_t id_ref;
  uint16_t literal_integer;
  uint16_t literal_string;
  uint16_t literal_context_dependent_number;
  uint16_t literal_ext_inst_integer;
  uint16_t literal_spec_constant_op_integer;
};
const WellKnownKinds& GetWellKnownKinds();

// --- Cold-start priors (generated; see docs/development/ratio.md item 7) -----
// Pool of SymbolCdf contents (16 uint16 offsets from the uniform CDF, warm-up
// count 0); index 0 is the uniform table.
const uint16_t* GetPriorCdf(uint16_t index);
uint16_t NumPriorCdfs();
// Relative weight of an instruction the logical layout allows in a section
// against one it does not (1).
constexpr uint32_t kOpcodePriorLegalWeight = 64;
// Opcode-index tree prior for a section (Section value): 69 pool indices,
// root, mid[0..3], then leaf[(top << 4) | mid].
const uint16_t* GetOpcodeSectionPrior(uint8_t section);
// The legality mask that prior was built from: 32 words, bit i = core
// instruction index i (tests rebuild the prior from it).
const uint32_t* GetOpcodeSectionLegal(uint8_t section);
// Priors for an 8-bit index tree over [0, n): the root for n (n >= 256 is
// uniform), and the leaf holding the last partial nibble group (n % 16 valid
// entries; 0 means uniform).
uint16_t GetIndexRootPrior(uint32_t n);
uint16_t GetIndexLeafPrior(uint32_t partial);
// String order-0 byte-tree priors (pool indices), built from GetStringPrimer()
// byte counts plus kStringOrder0FloorWeight per byte so every byte stays
// codable: 16-way high-nibble root and 16-way low-nibble leaf per high nibble.
constexpr uint32_t kStringOrder0FloorWeight = 4;
uint16_t GetStringOrder0RootPrior();
uint16_t GetStringOrder0LeafPrior(uint32_t high);
// Header priors (pool indices): the grammar's major version, and minor
// versions 0..the grammar's minor.
uint16_t GetVersionMajorPrior();
uint16_t GetVersionMinorPrior();
// Number of generator (tool) IDs registered in spir-v.xml; they are
// contiguous from 0.
uint32_t NumRegisteredGenerators();

}  // namespace v1
}  // namespace arixv
